"""Torch references for Gated DeltaNet helper kernels."""

from itertools import pairwise

import torch
import torch.nn.functional as F


def _validated_packed_prefill_offsets(
    cu_seqlens: torch.Tensor,
    *,
    total_tokens: int,
    device: torch.device,
) -> tuple[int, ...]:
    """Copy and validate offsets before the serial fallback indexes tensors."""

    if (
        cu_seqlens.ndim != 1
        or cu_seqlens.dtype != torch.int32
        or cu_seqlens.device != device
        or not cu_seqlens.is_contiguous()
    ):
        raise ValueError(
            "cu_seqlens must be contiguous 1D int32 on the query device"
        )
    offsets = tuple(int(value) for value in cu_seqlens.detach().cpu().tolist())
    if (
        not offsets
        or offsets[0] != 0
        or offsets[-1] != total_tokens
        or any(value < 0 or value > total_tokens for value in offsets)
        or any(left > right for left, right in pairwise(offsets))
    ):
        raise ValueError(
            "cu_seqlens must start at 0, be monotone within the token range, "
            "and end at the total token count"
        )
    return offsets


def _normalize_activation(activation: str | None) -> str | None:
    if activation in (None, "none", ""):
        return None
    if activation in ("silu", "swish"):
        return "silu"
    raise ValueError(f"unsupported causal_conv1d_update activation={activation!r}")


def causal_conv1d_update_torch(
    x: torch.Tensor,
    conv_state: torch.Tensor,
    weight: torch.Tensor,
    bias: torch.Tensor | None = None,
    activation: str | None = "silu",
    *,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Reference depthwise decode update.

    Matches ``causal_conv1d_update`` for the single-token decode case:
    update ``conv_state`` in-place with ``x`` and return the current
    depthwise convolution output.
    """

    act = _normalize_activation(activation)
    if x.ndim == 3 and x.shape[-1] == 1:
        x2 = x.squeeze(-1)
    elif x.ndim == 2:
        x2 = x
    else:
        raise ValueError(
            "causal_conv1d_update_torch expects x with shape [B, D] or [B, D, 1], "
            f"got {tuple(x.shape)}"
        )
    if conv_state.ndim != 3:
        raise ValueError(f"conv_state must be [B, D, K], got {tuple(conv_state.shape)}")
    if weight.ndim != 2:
        raise ValueError(f"weight must be [D, K], got {tuple(weight.shape)}")
    if x2.shape != conv_state.shape[:2]:
        raise ValueError(
            f"x shape {tuple(x2.shape)} must match conv_state batch/channel "
            f"{tuple(conv_state.shape[:2])}"
        )
    if weight.shape != conv_state.shape[1:]:
        raise ValueError(
            f"weight shape {tuple(weight.shape)} must match conv_state channel/kernel "
            f"{tuple(conv_state.shape[1:])}"
        )
    if bias is not None and bias.shape != (conv_state.shape[1],):
        raise ValueError(
            f"bias shape must be ({conv_state.shape[1]},), got {tuple(bias.shape)}"
        )
    if out is not None and out.shape != x2.shape:
        raise ValueError(f"out shape must be {tuple(x2.shape)}, got {tuple(out.shape)}")

    state_len = conv_state.shape[-1]
    if state_len > 1:
        conv_state[:, :, :-1].copy_(conv_state[:, :, 1:].clone())
    conv_state[:, :, -1].copy_(x2)
    result = (conv_state * weight.unsqueeze(0)).sum(dim=-1)
    if bias is not None:
        result = result + bias
    if act == "silu":
        result = F.silu(result)
    result = result.to(dtype=x2.dtype)
    if out is not None:
        out.copy_(result)
        return out
    return result


def causal_conv1d_update_indexed_torch(
    x: torch.Tensor,
    conv_state: torch.Tensor,
    weight: torch.Tensor,
    state_indices: torch.Tensor,
    bias: torch.Tensor | None = None,
    activation: str | None = "silu",
    *,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Reference decode conv update for compact inputs and indexed state rows."""

    if x.ndim == 3 and x.shape[-1] == 1:
        x2 = x.squeeze(-1)
    elif x.ndim == 2:
        x2 = x
    else:
        raise ValueError(
            "causal_conv1d_update_indexed_torch expects x with shape [B, D] "
            f"or [B, D, 1], got {tuple(x.shape)}"
        )
    if state_indices.ndim != 1 or state_indices.shape[0] != x2.shape[0]:
        raise ValueError(
            "state_indices must be [B] matching x batch dimension, got "
            f"{tuple(state_indices.shape)} for x={tuple(x2.shape)}"
        )
    indices = state_indices.to(device=conv_state.device, dtype=torch.long)
    state_view = conv_state.index_select(0, indices).clone()
    result = causal_conv1d_update_torch(
        x2,
        state_view,
        weight,
        bias,
        activation,
        out=out,
    )
    conv_state.index_copy_(0, indices, state_view)
    return result


def causal_conv1d_packed_torch(
    x: torch.Tensor,
    weight: torch.Tensor,
    seq_idx: torch.Tensor | None = None,
    bias: torch.Tensor | None = None,
    activation: str | None = "silu",
    *,
    final_state: torch.Tensor,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Reference packed prefill depthwise causal convolution."""

    act = _normalize_activation(activation)
    if x.ndim != 3:
        raise ValueError(f"x must be [B, D, T], got {tuple(x.shape)}")
    if weight.ndim != 2:
        raise ValueError(f"weight must be [D, K], got {tuple(weight.shape)}")
    batch, channels, seqlen = x.shape
    if weight.shape[0] != channels:
        raise ValueError(
            f"weight channels must be {channels}, got {tuple(weight.shape)}"
        )
    if bias is not None and bias.shape != (channels,):
        raise ValueError(f"bias shape must be ({channels},), got {tuple(bias.shape)}")
    if seq_idx is not None and seq_idx.shape != (batch, seqlen):
        raise ValueError(
            f"seq_idx shape must be {(batch, seqlen)}, got {tuple(seq_idx.shape)}"
        )
    if seq_idx is None:
        raise ValueError("causal_conv1d_packed final_state requires seq_idx")
    if final_state is None:
        raise ValueError("causal_conv1d_packed requires final_state")
    if final_state.shape[1:] != (channels, weight.shape[1]):
        raise ValueError(
            f"final_state shape must be [*, {channels}, {weight.shape[1]}], "
            f"got {tuple(final_state.shape)}"
        )
    if out is not None and out.shape != x.shape:
        raise ValueError(f"out shape must be {tuple(x.shape)}, got {tuple(out.shape)}")

    x_f32 = x.float()
    weight_f32 = weight.float()
    kernel_size = weight.shape[1]
    final_state.zero_()
    if x.is_cuda and torch.cuda.is_current_stream_capturing():
        # Graph-capture path: one sequence per batch row (spec verify / decode block).
        # The conv state is simply the last kernel_size inputs; scatter via device
        # indices so there are no host reads of seq_idx during capture.
        n = min(kernel_size, seqlen)
        fs_block = final_state.new_zeros(batch, channels, kernel_size)
        fs_block[:, :, kernel_size - n:] = x[:, :, seqlen - n:].to(final_state.dtype)
        final_state.index_copy_(0, seq_idx[:, -1].to(torch.long), fs_block)
    else:
        for b in range(batch):
            for token in range(seqlen):
                row = int(seq_idx[b, token])
                if row < 0:
                    continue
                if token + 1 < seqlen and int(seq_idx[b, token + 1]) == row:
                    continue
                for k in range(kernel_size):
                    src = token - (kernel_size - 1) + k
                    if src >= 0 and int(seq_idx[b, src]) == row:
                        final_state[row, :, k].copy_(x[b, :, src])
    result = x_f32 * weight_f32[:, -1].reshape(1, channels, 1)
    for lag in range(1, min(kernel_size, seqlen)):
        valid = seq_idx[:, lag:] == seq_idx[:, : seqlen - lag]
        contrib = (
            x_f32[:, :, : seqlen - lag]
            * weight_f32[:, kernel_size - 1 - lag].reshape(1, channels, 1)
        )
        result[:, :, lag:].add_(contrib * valid[:, None, :].to(contrib.dtype))
    if bias is not None:
        result = result + bias.reshape(1, channels, 1)
    if act == "silu":
        result = F.silu(result)
    result = result.to(x.dtype)
    if out is not None:
        out.copy_(result)
        return out
    return result


def packed_recurrent_gated_delta_rule_decode_torch(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    recurrent_state: torch.Tensor,
    *,
    out: torch.Tensor | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Reference Qwen GDN single-token packed recurrent update.

    ``mixed_qkv`` is the post-conv packed tensor with layout
    ``[q, k, v]`` in the last dimension. ``recurrent_state`` is updated
    in-place and returned as the final state.
    """

    if mixed_qkv.ndim != 2:
        raise ValueError(f"mixed_qkv must be [B, D], got {tuple(mixed_qkv.shape)}")
    if a.ndim != 3 or b.ndim != 3:
        raise ValueError(f"a/b must be [B, 1, H], got {tuple(a.shape)} / {tuple(b.shape)}")
    if recurrent_state.ndim != 4:
        raise ValueError(
            f"recurrent_state must be [B, H, K, V], got {tuple(recurrent_state.shape)}"
        )
    batch, num_v_heads, k_dim, v_dim = recurrent_state.shape
    value_dim = num_v_heads * v_dim
    qk_packed_dim = mixed_qkv.shape[1] - value_dim
    if qk_packed_dim <= 0 or qk_packed_dim % (2 * k_dim) != 0:
        raise ValueError(
            "mixed_qkv last dim must be 2 * K * D + V * D for recurrent state "
            f"{tuple(recurrent_state.shape)}, got {tuple(mixed_qkv.shape)}"
        )
    num_k_heads = qk_packed_dim // (2 * k_dim)
    qk_dim = num_k_heads * k_dim
    expected_dim = 2 * qk_dim + value_dim
    if mixed_qkv.shape != (batch, expected_dim):
        raise ValueError(
            f"mixed_qkv shape must be {(batch, expected_dim)}, got {tuple(mixed_qkv.shape)}"
        )
    if a.shape != (batch, 1, num_v_heads) or b.shape != (batch, 1, num_v_heads):
        raise ValueError(
            f"a/b must be {(batch, 1, num_v_heads)}, got {tuple(a.shape)} / {tuple(b.shape)}"
        )
    if A_log.shape != (num_v_heads,) or dt_bias.shape != (num_v_heads,):
        raise ValueError(
            f"A_log/dt_bias must be {(num_v_heads,)}, "
            f"got {tuple(A_log.shape)} / {tuple(dt_bias.shape)}"
        )
    if num_v_heads % num_k_heads != 0:
        raise ValueError(
            f"num_v_heads must be a multiple of num_k_heads, got {num_v_heads=} "
            f"{num_k_heads=}"
        )
    if out is not None and out.shape != (batch, 1, num_v_heads, v_dim):
        raise ValueError(
            f"out shape must be {(batch, 1, num_v_heads, v_dim)}, got {tuple(out.shape)}"
        )

    query, key, value = torch.split(mixed_qkv, [qk_dim, qk_dim, value_dim], dim=-1)
    query = query.reshape(batch, num_k_heads, k_dim).float()
    key = key.reshape(batch, num_k_heads, k_dim).float()
    value = value.reshape(batch, num_v_heads, v_dim).float()

    query = query * torch.rsqrt((query * query).sum(dim=-1, keepdim=True) + 1e-6)
    key = key * torch.rsqrt((key * key).sum(dim=-1, keepdim=True) + 1e-6)
    k_head_for_v = (
        torch.arange(num_v_heads, device=mixed_qkv.device, dtype=torch.long)
        * num_k_heads
        // num_v_heads
    )
    query = query.index_select(1, k_head_for_v)
    key = key.index_select(1, k_head_for_v)
    query = query * (k_dim**-0.5)

    beta = b.squeeze(1).sigmoid().float()
    decay = (-A_log.float().exp().reshape(1, num_v_heads) * F.softplus(
        a.squeeze(1).float() + dt_bias.float().reshape(1, num_v_heads)
    )).exp()

    recurrent_state.mul_(decay[:, :, None, None])
    state_3d = recurrent_state.reshape(batch * num_v_heads, k_dim, v_dim)
    key_2d = key.reshape(batch * num_v_heads, k_dim)
    query_2d = query.reshape(batch * num_v_heads, k_dim)
    kv_mem = torch.bmm(key_2d[:, None, :], state_3d).reshape(batch, num_v_heads, v_dim)
    delta = (value - kv_mem) * beta[:, :, None]
    state_3d.baddbmm_(
        key_2d[:, :, None],
        delta.reshape(batch * num_v_heads, v_dim)[:, None, :],
        beta=1.0,
        alpha=1.0,
    )
    result = torch.bmm(query_2d[:, None, :], state_3d).reshape(batch, num_v_heads, v_dim)
    result = result.to(mixed_qkv.dtype)
    result = result.unsqueeze(1)
    if out is not None:
        out.copy_(result)
        return out, recurrent_state
    return result, recurrent_state


def packed_recurrent_gated_delta_rule_decode_indexed_torch(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    recurrent_state: torch.Tensor,
    state_indices: torch.Tensor,
    *,
    out: torch.Tensor | None = None,
) -> tuple[torch.Tensor, None]:
    """Reference recurrent decode for compact inputs and indexed state rows."""

    if state_indices.ndim != 1 or state_indices.shape[0] != mixed_qkv.shape[0]:
        raise ValueError(
            "state_indices must be [B] matching mixed_qkv batch dimension, "
            f"got {tuple(state_indices.shape)} for mixed_qkv={tuple(mixed_qkv.shape)}"
        )
    indices = state_indices.to(device=recurrent_state.device, dtype=torch.long)
    state_view = recurrent_state.index_select(0, indices).clone()
    result, _ = packed_recurrent_gated_delta_rule_decode_torch(
        mixed_qkv,
        a,
        b,
        A_log,
        dt_bias,
        state_view,
        out=out,
    )
    recurrent_state.index_copy_(0, indices, state_view)
    return result, None


def packed_recurrent_gated_delta_rule_decode_replay_indexed_torch(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    checkpoint_state: torch.Tensor,
    replay_k: torch.Tensor,
    replay_u: torch.Tensor,
    replay_g: torch.Tensor,
    replay_lengths: torch.Tensor,
    state_indices: torch.Tensor,
    *,
    out: torch.Tensor | None = None,
) -> tuple[torch.Tensor, None]:
    """Reference ReplaySSM-style GDN decode.

    ``checkpoint_state`` stores the last flushed recurrent state as
    ``[state_slot, head, value, key]`` so ReplaySSM decode can stream one
    contiguous key tile for each output-value row.  ``replay_*`` caches the
    unflushed GDN update inputs per state row:
    normalized ``k``, correction vector ``u``, and log-decay ``g``.
    """

    if mixed_qkv.ndim != 2:
        raise ValueError(f"mixed_qkv must be [B, D], got {tuple(mixed_qkv.shape)}")
    if checkpoint_state.ndim != 4:
        raise ValueError(
            "checkpoint_state must be [S, H, V, K], "
            f"got {tuple(checkpoint_state.shape)}"
        )
    if state_indices.ndim != 1 or state_indices.shape[0] != mixed_qkv.shape[0]:
        raise ValueError(
            "state_indices must be [B] matching mixed_qkv batch dimension, "
            f"got {tuple(state_indices.shape)} for mixed_qkv={tuple(mixed_qkv.shape)}"
        )

    batch = mixed_qkv.shape[0]
    state_slots, num_v_heads, v_dim, k_dim = checkpoint_state.shape
    capacity = replay_k.shape[1]
    value_dim = num_v_heads * v_dim
    qk_packed_dim = mixed_qkv.shape[1] - value_dim
    if qk_packed_dim <= 0 or qk_packed_dim % (2 * k_dim) != 0:
        raise ValueError(
            "mixed_qkv last dim must be 2 * K * D + V * D for checkpoint state "
            f"{tuple(checkpoint_state.shape)}, got {tuple(mixed_qkv.shape)}"
        )
    num_k_heads = qk_packed_dim // (2 * k_dim)
    if num_v_heads % num_k_heads != 0:
        raise ValueError(
            f"num_v_heads must be a multiple of num_k_heads, got {num_v_heads=} "
            f"{num_k_heads=}"
        )
    expected_dim = 2 * num_k_heads * k_dim + value_dim
    # The replay key ring is keyed by VALUE head in production (qwen_compat
    # _ensure_replay_state / paged_cache size replay_k by num_v_heads; the native
    # GQA QwenReplayDecodeIndexed kernel indexes replay_k[..., head, :] by value
    # head and applies the k->v fan-out to mixed_qkv). The symmetric dispatch's
    # native kernel instead keys a GQA shape's ring by k-head, so this shared
    # fallback accepts EITHER width and folds accordingly: detect the ring head
    # count from replay_k itself. (replay_u/g and the gates are always v-head.)
    ring_heads = int(replay_k.shape[2]) if replay_k.ndim == 4 else -1
    if ring_heads not in (num_v_heads, num_k_heads):
        raise ValueError(
            "replay_k head dim must be num_v_heads "
            f"({num_v_heads}) or num_k_heads ({num_k_heads}), "
            f"got replay_k shape {tuple(replay_k.shape)}"
        )
    value_head_ring = ring_heads == num_v_heads
    expected_replay_k = (state_slots, capacity, ring_heads, k_dim)
    expected_replay_u = (state_slots, capacity, num_v_heads, v_dim)
    expected_replay_g = (state_slots, capacity, num_v_heads)
    if mixed_qkv.shape != (batch, expected_dim):
        raise ValueError(
            f"mixed_qkv shape must be {(batch, expected_dim)}, got {tuple(mixed_qkv.shape)}"
        )
    if replay_k.shape != expected_replay_k or replay_u.shape != expected_replay_u:
        raise ValueError(
            "replay_k/replay_u must be "
            f"{expected_replay_k} / {expected_replay_u}, "
            f"got {tuple(replay_k.shape)} / {tuple(replay_u.shape)}"
        )
    if replay_g.shape != expected_replay_g:
        raise ValueError(f"replay_g must be {expected_replay_g}, got {tuple(replay_g.shape)}")
    if replay_lengths.shape != (state_slots,):
        raise ValueError(
            f"replay_lengths must be {(state_slots,)}, got {tuple(replay_lengths.shape)}"
        )
    if a.shape != (batch, 1, num_v_heads) or b.shape != (batch, 1, num_v_heads):
        raise ValueError(
            f"a/b must be {(batch, 1, num_v_heads)}, "
            f"got {tuple(a.shape)} / {tuple(b.shape)}"
        )
    if A_log.shape != (num_v_heads,) or dt_bias.shape != (num_v_heads,):
        raise ValueError(
            f"A_log/dt_bias must be {(num_v_heads,)}, "
            f"got {tuple(A_log.shape)} / {tuple(dt_bias.shape)}"
        )
    if out is None:
        out = torch.empty(
            (batch, 1, num_v_heads, v_dim),
            device=mixed_qkv.device,
            dtype=mixed_qkv.dtype,
        )
    elif out.shape != (batch, 1, num_v_heads, v_dim):
        raise ValueError(
            f"out shape must be {(batch, 1, num_v_heads, v_dim)}, got {tuple(out.shape)}"
        )

    query, key, value = torch.split(
        mixed_qkv,
        [num_k_heads * k_dim, num_k_heads * k_dim, value_dim],
        dim=-1,
    )
    query = query.reshape(batch, num_k_heads, k_dim).float()
    key = key.reshape(batch, num_k_heads, k_dim).float()
    value = value.reshape(batch, num_v_heads, v_dim).float()
    query = query * torch.rsqrt((query * query).sum(dim=-1, keepdim=True) + 1e-6)
    key = key * torch.rsqrt((key * key).sum(dim=-1, keepdim=True) + 1e-6)
    k_head_for_v = (
        torch.arange(num_v_heads, device=mixed_qkv.device, dtype=torch.long)
        * num_k_heads
        // num_v_heads
    )
    query_for_v = query.index_select(1, k_head_for_v)
    key_for_v = key.index_select(1, k_head_for_v)
    query_for_v = query_for_v * (k_dim**-0.5)

    beta = b.squeeze(1).sigmoid().float()
    gate_log = (
        -A_log.float().exp().reshape(1, num_v_heads)
        * F.softplus(a.squeeze(1).float() + dt_bias.float().reshape(1, num_v_heads))
    )
    alpha = gate_log.exp()
    indices = state_indices.to(device=checkpoint_state.device, dtype=torch.long)

    for batch_idx in range(batch):
        state_idx = int(indices[batch_idx].item())
        length = int(replay_lengths[state_idx].item())
        if length < 0 or length > capacity:
            raise ValueError(f"invalid replay length {length} for capacity {capacity}")

        checkpoint = checkpoint_state[state_idx].float()
        k_buf = replay_k[state_idx, :length].float()
        u_buf = replay_u[state_idx, :length].float()
        g_buf = replay_g[state_idx, :length].float()
        if length:
            suffix_log = torch.zeros(
                (length, num_v_heads),
                device=mixed_qkv.device,
                dtype=torch.float32,
            )
            running = torch.zeros((num_v_heads,), device=mixed_qkv.device, dtype=torch.float32)
            for pos in range(length - 1, -1, -1):
                suffix_log[pos].copy_(running)
                running = running + g_buf[pos]
            checkpoint_decay = running.exp()
        else:
            suffix_log = torch.empty(
                (0, num_v_heads),
                device=mixed_qkv.device,
                dtype=torch.float32,
            )
            checkpoint_decay = torch.ones(
                (num_v_heads,),
                device=mixed_qkv.device,
                dtype=torch.float32,
            )

        state_q = torch.empty((num_v_heads, v_dim), device=mixed_qkv.device, dtype=torch.float32)
        state_k = torch.empty_like(state_q)
        materialized = torch.empty_like(checkpoint)
        for head in range(num_v_heads):
            # Ring row index: value head for the v-head ring (each row already
            # holds this value head's shared-k-head normalized key); the shared
            # k-head for a legacy k-head ring.
            ring_head = head if value_head_ring else int(k_head_for_v[head].item())
            state_h = checkpoint_decay[head] * checkpoint[head].transpose(0, 1)
            for pos in range(length):
                coeff = suffix_log[pos, head].exp()
                state_h = (
                    state_h
                    + coeff
                    * k_buf[pos, ring_head, :, None]
                    * u_buf[pos, head, None, :]
                )
            materialized[head].copy_(state_h.transpose(0, 1))
            state_k[head] = (state_h * key_for_v[batch_idx, head, :, None]).sum(dim=0)
            state_q[head] = (state_h * query_for_v[batch_idx, head, :, None]).sum(dim=0)

        u_current = (value[batch_idx] - alpha[batch_idx, :, None] * state_k) * beta[
            batch_idx, :, None
        ]
        k_dot_q = (key_for_v[batch_idx] * query_for_v[batch_idx]).sum(dim=-1)
        out[batch_idx, 0].copy_(
            (alpha[batch_idx, :, None] * state_q + u_current * k_dot_q[:, None]).to(out.dtype)
        )

        if length + 1 >= capacity:
            for head in range(num_v_heads):
                # The current token's key for this value head -- the normalized
                # shared-k-head key (key_for_v[head] == key[k_head_for_v[head]]).
                next_state = (
                    alpha[batch_idx, head] * materialized[head].transpose(0, 1)
                    + key_for_v[batch_idx, head, :, None] * u_current[head, None, :]
                )
                checkpoint_state[state_idx, head].copy_(next_state.transpose(0, 1))
            replay_lengths[state_idx] = 0
        else:
            # Append the current token's normalized key in the ring's own head
            # layout: the fanned-out value-head key for a v-head ring (matching
            # the native verify/decode kernels), or the raw k-head key otherwise.
            new_k = key_for_v[batch_idx] if value_head_ring else key[batch_idx]
            replay_k[state_idx, length].copy_(new_k.to(replay_k.dtype))
            replay_u[state_idx, length].copy_(u_current.to(replay_u.dtype))
            replay_g[state_idx, length].copy_(gate_log[batch_idx].to(replay_g.dtype))
            replay_lengths[state_idx] = length + 1

    return out, None


def packed_recurrent_gated_delta_rule_verify_replay_indexed_torch(
    mixed_qkv: torch.Tensor,  # [B, T, 2*H*K + H*V] bf16
    a: torch.Tensor,  # [B, T, H]
    b: torch.Tensor,  # [B, T, H]
    A_log: torch.Tensor,  # [H] fp32
    dt_bias: torch.Tensor,  # [H] fp32
    checkpoint_state: torch.Tensor,  # [S, H, V, K] fp32 (mutated on flush)
    replay_k: torch.Tensor,  # [S, C, H, K] bf16 (appended)
    replay_u: torch.Tensor,  # [S, C, H, V] fp32 (appended)
    replay_g: torch.Tensor,  # [S, C, H] fp32 (appended)
    replay_lengths: torch.Tensor,  # [S] int32 (cursor, advanced)
    state_indices: torch.Tensor,  # [B] int64
    *,
    out: torch.Tensor | None = None,  # [B, T, H, V]
) -> tuple[torch.Tensor, None]:
    """Reference multi-token ReplaySSM GDN verify (Algorithm 4).

    The block-decode form of :func:`...decode_replay_indexed_torch`: streams the T
    block tokens through the same recurrence, reading each token's output from the
    checkpoint + ring-buffer window (causal up to the prior token) and appending its
    ``(k, u, g)`` so the next token sees it. This is the oracle/fallback for the
    fused ``QwenReplayVerifyIndexed`` CuTe kernel; numerically matches the
    single-token decode-replay kernel looped over the block (bf16 rounding).
    """
    if mixed_qkv.ndim != 3:
        raise ValueError(f"mixed_qkv must be [B, T, D], got {tuple(mixed_qkv.shape)}")
    if checkpoint_state.ndim != 4:
        raise ValueError(f"checkpoint_state must be [S, H, V, K], got {tuple(checkpoint_state.shape)}")
    batch, seqlen, _ = mixed_qkv.shape
    state_slots, heads, v_dim, k_dim = checkpoint_state.shape
    capacity = replay_k.shape[1]
    if heads <= 0 or k_dim <= 0 or v_dim <= 0:
        raise ValueError(f"invalid checkpoint_state shape: {(state_slots, heads, v_dim, k_dim)}")
    if mixed_qkv.shape[-1] <= heads * v_dim:
        raise ValueError(
            f"mixed_qkv last dim must be > {heads * v_dim}, got {mixed_qkv.shape[-1]} "
            f"for heads={heads}, v_dim={v_dim}"
        )
    if (mixed_qkv.shape[-1] - heads * v_dim) % (2 * k_dim) != 0:
        raise ValueError(
            f"mixed_qkv last dim must be (2*KH + H)*k_dim for integer KH, got {mixed_qkv.shape[-1]} "
            f"with heads={heads}, k_dim={k_dim}"
        )
    kh = (mixed_qkv.shape[-1] - heads * k_dim) // (2 * k_dim)
    if kh <= 0 or heads % kh != 0:
        raise ValueError(
            f"unsupported mixed_qkv layout for heads={heads}, k_dim={k_dim}; inferred KH={kh}"
        )
    expected_dim = (2 * kh + heads) * k_dim
    if mixed_qkv.shape[-1] != expected_dim:
        raise ValueError(f"mixed_qkv last dim must be {expected_dim}, got {mixed_qkv.shape[-1]}")
    if a.shape != (batch, seqlen, heads) or b.shape != (batch, seqlen, heads):
        raise ValueError(f"a/b must be {(batch, seqlen, heads)}, got {tuple(a.shape)} / {tuple(b.shape)}")
    if out is None:
        out = torch.empty((batch, seqlen, heads, v_dim), device=mixed_qkv.device, dtype=mixed_qkv.dtype)

    qkv_split = [kh * k_dim, kh * k_dim, heads * v_dim]
    query, key, value = torch.split(mixed_qkv, qkv_split, dim=-1)
    query = query.reshape(batch, seqlen, kh, k_dim).float()
    key = key.reshape(batch, seqlen, kh, k_dim).float()
    value = value.reshape(batch, seqlen, heads, v_dim).float()
    k_to_v = torch.arange(heads, device=mixed_qkv.device, dtype=torch.long) // (heads // kh)
    query = query.index_select(2, k_to_v)
    key = key.index_select(2, k_to_v)
    query = query * torch.rsqrt((query * query).sum(-1, keepdim=True) + 1e-6) * (k_dim**-0.5)
    key = key * torch.rsqrt((key * key).sum(-1, keepdim=True) + 1e-6)
    beta = b.sigmoid().float()  # [B,T,H]
    gate_log = -A_log.float().exp().reshape(1, 1, heads) * F.softplus(a.float() + dt_bias.float().reshape(1, 1, heads))
    alpha = gate_log.exp()  # [B,T,H]
    indices = state_indices.to(device=checkpoint_state.device, dtype=torch.long)

    for bi in range(batch):
        si = int(indices[bi].item())
        length = int(replay_lengths[si].item())
        # Reconstruct S [H, K, V] from checkpoint + ring-buffer window (suffix decay).
        suffix = torch.zeros(length, heads, device=mixed_qkv.device)
        running = torch.zeros(heads, device=mixed_qkv.device)
        for pos in range(length - 1, -1, -1):
            suffix[pos] = running
            running = running + replay_g[si, pos].float()
        S = running.exp()[:, None, None] * checkpoint_state[si].transpose(1, 2)  # [H,V,K]->[H,K,V]
        for pos in range(length):
            coeff = suffix[pos].exp()
            S = S + coeff[:, None, None] * replay_k[si, pos].float()[:, :, None] * replay_u[si, pos][:, None, :]
        # Verify contract (matches QwenReplayVerifyIndexed and the native
        # ``packed_recurrent_gated_delta_rule_verify_replay_indexed`` dispatch):
        # APPEND the T block tokens' (k, u, g) to the ring at [length .. length+T-1]
        # and leave ``replay_lengths`` UNCHANGED. The spec-loop commit advances the
        # cursor by ``accept + 1`` afterwards, so accepting only the matched prefix
        # commits exactly those drafts. The checkpoint must NOT be folded here: the
        # spec loop forces a state-preserving materialize before any block that
        # would overflow the ring, so the native verify never flushes mid-block.
        # Advancing the cursor (or flushing) here would, after the caller adds
        # accept+1, commit unaccepted drafts and diverge from greedy whenever the
        # native verify cubin is unavailable/disabled.
        if length + seqlen > capacity:
            raise ValueError(
                f"verify block of {seqlen} tokens overflows replay ring at "
                f"length {length} (capacity {capacity}); the caller must flush "
                "the ring before a block that would not fit"
            )
        for t in range(seqlen):
            q_t, k_t, v_t = query[bi, t], key[bi, t], value[bi, t]
            a_t, b_t, g_t = alpha[bi, t], beta[bi, t], gate_log[bi, t]
            s_k = (S * k_t[:, :, None]).sum(1)  # [H,V] = sum_K S[k,v]*k[k]
            s_q = (S * q_t[:, :, None]).sum(1)  # [H,V]
            u_t = b_t[:, None] * (v_t - a_t[:, None] * s_k)
            kq = (k_t * q_t).sum(-1)  # [H]
            out[bi, t] = (a_t[:, None] * s_q + u_t * kq[:, None]).to(out.dtype)
            S = a_t[:, None, None] * S + k_t[:, :, None] * u_t[:, None, :]
            pos = length + t
            replay_k[si, pos].copy_(k_t.to(replay_k.dtype))
            replay_u[si, pos].copy_(u_t.to(replay_u.dtype))
            replay_g[si, pos].copy_(g_t.to(replay_g.dtype))
        # replay_lengths[si] intentionally left at ``length`` (see above).

    return out, None


def materialize_replay_state_indexed_torch(
    recurrent_state: torch.Tensor,
    checkpoint_state: torch.Tensor,
    replay_k: torch.Tensor,
    replay_u: torch.Tensor,
    replay_g: torch.Tensor,
    replay_lengths: torch.Tensor,
    state_indices: torch.Tensor,
    *,
    write_recurrent: bool = True,
) -> torch.Tensor:
    """Fold ReplaySSM checkpoint+ring rows into both recurrent state layouts.

    ``recurrent_state`` is ``[S,H,K,V]`` and ``checkpoint_state`` is
    ``[S,H,V,K]``. The selected rows are reconstructed in the same scalar order
    as the native verify kernel, then the caller may clear ``replay_lengths``.
    """

    if recurrent_state.ndim != 4:
        raise ValueError(
            f"recurrent_state must be [S,H,K,V], got {tuple(recurrent_state.shape)}"
        )
    if checkpoint_state.ndim != 4:
        raise ValueError(
            f"checkpoint_state must be [S,H,V,K], got {tuple(checkpoint_state.shape)}"
        )
    state_slots, heads, key_dim, value_dim = recurrent_state.shape
    capacity = replay_k.shape[1]
    if checkpoint_state.shape != (state_slots, heads, value_dim, key_dim):
        raise ValueError(
            "checkpoint_state shape must be "
            f"{(state_slots, heads, value_dim, key_dim)}, got {tuple(checkpoint_state.shape)}"
        )
    if replay_k.shape != (state_slots, capacity, heads, key_dim):
        raise ValueError(f"bad replay_k shape {tuple(replay_k.shape)}")
    if replay_u.shape != (state_slots, capacity, heads, value_dim):
        raise ValueError(f"bad replay_u shape {tuple(replay_u.shape)}")
    if replay_g.shape != (state_slots, capacity, heads):
        raise ValueError(f"bad replay_g shape {tuple(replay_g.shape)}")
    if replay_lengths.shape != (state_slots,):
        raise ValueError(f"bad replay_lengths shape {tuple(replay_lengths.shape)}")
    if state_indices.ndim != 1:
        raise ValueError(f"state_indices must be [B], got {tuple(state_indices.shape)}")

    indices = state_indices.to(device=recurrent_state.device, dtype=torch.long)
    for state_idx_t in indices:
        state_idx = int(state_idx_t.item())
        length = int(replay_lengths[state_idx].item())
        if length < 0 or length > capacity:
            raise ValueError(f"invalid replay length {length} for capacity {capacity}")
        for head in range(heads):
            log_decay = replay_g[state_idx, :length, head].float()
            running = log_decay.sum()
            state_h = (
                running.exp()
                * checkpoint_state[state_idx, head].float().transpose(0, 1)
            )
            for pos in range(length):
                suffix = log_decay[pos + 1 :].sum().exp()
                state_h = state_h + (
                    suffix
                    * replay_k[state_idx, pos, head].float()[:, None]
                    * replay_u[state_idx, pos, head].float()[None, :]
                )
            if write_recurrent:
                recurrent_state[state_idx, head].copy_(state_h.to(recurrent_state.dtype))
            checkpoint_state[state_idx, head].copy_(
                state_h.transpose(0, 1).to(checkpoint_state.dtype)
            )
    return recurrent_state


def packed_recurrent_gated_delta_rule_prefill_torch(
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    g: torch.Tensor,
    beta: torch.Tensor,
    cu_seqlens: torch.Tensor,
    *,
    initial_state: torch.Tensor | None = None,
    output_final_state: bool = True,
    use_qk_l2norm_in_kernel: bool = False,
    out: torch.Tensor | None = None,
    final_state: torch.Tensor | None = None,
    final_state_indices: torch.Tensor | None = None,
) -> tuple[torch.Tensor, torch.Tensor | None]:
    """Reference packed prefill recurrent GDN update.

    This is the serial recurrent rule equivalent of FLA's chunk implementation.
    It is intentionally simple and follows the Qwen fallback math.
    """

    if query.ndim != 4 or query.shape[0] != 1:
        raise ValueError(f"query must be [1, T, H, D], got {tuple(query.shape)}")
    if key.shape != query.shape:
        raise ValueError(
            f"key must match query shape {tuple(query.shape)}, got {tuple(key.shape)}"
        )
    if value.ndim != 4 or value.shape[0] != 1 or value.shape[1] != query.shape[1]:
        raise ValueError(
            f"value must be [1, T, V, D], got {tuple(value.shape)} for query "
            f"{tuple(query.shape)}"
        )
    if value.shape[3] != query.shape[3]:
        raise ValueError(
            f"value head_dim must match query head_dim {query.shape[3]}, "
            f"got {value.shape[3]}"
        )
    if g.shape != value.shape[:3] or beta.shape != value.shape[:3]:
        raise ValueError(
            f"g/beta must be {tuple(value.shape[:3])}, "
            f"got {tuple(g.shape)} / {tuple(beta.shape)}"
        )
    if cu_seqlens.ndim != 1:
        raise ValueError(f"cu_seqlens must be 1D, got {tuple(cu_seqlens.shape)}")

    _, seqlen, num_k_heads, head_dim = query.shape
    num_v_heads = value.shape[2]
    if num_v_heads % num_k_heads != 0:
        raise ValueError(
            f"num_v_heads must be a multiple of num_k_heads, got {num_v_heads=} "
            f"{num_k_heads=}"
        )
    num_sequences = int(cu_seqlens.numel()) - 1
    offsets = _validated_packed_prefill_offsets(
        cu_seqlens,
        total_tokens=seqlen,
        device=query.device,
    )
    if not output_final_state:
        final_state = None
        final_state_indices = None
    indexed_final_state = final_state_indices is not None
    if indexed_final_state:
        if initial_state is not None:
            raise ValueError(
                "indexed BF16 final_state does not accept a sequence-major "
                "initial_state"
            )
        if (
            final_state_indices.ndim != 1
            or final_state_indices.shape != (num_sequences,)
            or final_state_indices.dtype != torch.int64
            or not final_state_indices.is_contiguous()
            or final_state_indices.device != query.device
        ):
            raise ValueError(
                "final_state_indices must be contiguous int64 "
                f"[{num_sequences}] on the query device"
            )
        if (
            final_state is None
            or final_state.ndim != 4
            or final_state.shape[1:] != (
                num_v_heads,
                value.shape[3],
                head_dim,
            )
            or final_state.dtype != torch.bfloat16
            or final_state.device != query.device
            or not final_state.is_contiguous()
        ):
            raise ValueError(
                "indexed final_state must be contiguous BF16 "
                f"[state_rows, {num_v_heads}, {value.shape[3]}, {head_dim}]"
            )
    if initial_state is not None and initial_state.shape != (
        num_sequences,
        num_v_heads,
        head_dim,
        head_dim,
    ):
        raise ValueError(
            "initial_state must be "
            f"{(num_sequences, num_v_heads, head_dim, head_dim)}, "
            f"got {tuple(initial_state.shape)}"
        )
    if (
        not indexed_final_state
        and final_state is not None
        and final_state.shape != (
            num_sequences,
            num_v_heads,
            head_dim,
            head_dim,
        )
    ):
        raise ValueError(
            "final_state must be "
            f"{(num_sequences, num_v_heads, head_dim, head_dim)}, "
            f"got {tuple(final_state.shape)}"
        )
    expected_out = (1, seqlen, num_v_heads, head_dim)
    if out is not None and out.shape != expected_out:
        raise ValueError(f"out shape must be {expected_out}, got {tuple(out.shape)}")

    query_f = query[0].float()
    key_f = key[0].float()
    if use_qk_l2norm_in_kernel:
        query_f = query_f * torch.rsqrt(
            (query_f * query_f).sum(dim=-1, keepdim=True) + 1e-6
        )
        key_f = key_f * torch.rsqrt(
            (key_f * key_f).sum(dim=-1, keepdim=True) + 1e-6
        )
    k_head_for_v = (
        torch.arange(num_v_heads, device=query.device, dtype=torch.long)
        * num_k_heads
        // num_v_heads
    )
    query_f = query_f.index_select(1, k_head_for_v)
    key_f = key_f.index_select(1, k_head_for_v)
    query_f = query_f * (head_dim**-0.5)
    value_f = value[0].float()
    beta_f = beta[0].float()
    decay_f = g[0].float().exp()

    result = (
        torch.empty(expected_out, device=query.device, dtype=query.dtype)
        if out is None
        else out
    )
    writes_result_directly = result.dtype == torch.float32
    result_work = (
        result[0]
        if writes_result_directly
        else torch.empty(
            (seqlen, num_v_heads, head_dim),
            device=query.device,
            dtype=torch.float32,
        )
    )
    state_out = None
    if output_final_state:
        if final_state is None:
            final_state = torch.empty(
                (num_sequences, num_v_heads, head_dim, head_dim),
                device=query.device,
                dtype=torch.float32,
            )
        state_out = final_state

    state_rows = (
        [int(x) for x in final_state_indices.detach().cpu().tolist()]
        if indexed_final_state
        else list(range(num_sequences))
    )
    if indexed_final_state and any(
        row < 0 or row >= int(final_state.shape[0]) for row in state_rows
    ):
        raise ValueError(
            "final_state_indices contains a row outside the final_state pool"
        )
    if indexed_final_state and len(set(state_rows)) != len(state_rows):
        raise ValueError("final_state_indices must contain unique state rows")
    for seq_idx, (start, end) in enumerate(zip(offsets[:-1], offsets[1:])):
        if indexed_final_state:
            state = torch.zeros(
                (num_v_heads, head_dim, head_dim),
                device=query.device,
                dtype=torch.float32,
            )
        elif state_out is not None:
            state = state_out[seq_idx]
            if initial_state is None:
                state.zero_()
            else:
                state.copy_(initial_state[seq_idx])
        elif initial_state is None:
            state = torch.zeros(
                (num_v_heads, head_dim, head_dim),
                device=query.device,
                dtype=torch.float32,
            )
        else:
            state = initial_state[seq_idx].float().clone()
        for token in range(start, end):
            state.mul_(decay_f[token, :, None, None])
            token_key = key_f[token]
            token_query = query_f[token]
            kv_mem = torch.bmm(token_key[:, None, :], state).squeeze(1)
            delta = (value_f[token] - kv_mem) * beta_f[token, :, None]
            state.baddbmm_(
                token_key[:, :, None],
                delta[:, None, :],
                beta=1.0,
                alpha=1.0,
            )
            token_out = torch.bmm(token_query[:, None, :], state).squeeze(1)
            result_work[token].copy_(token_out)
        if indexed_final_state and state_out is not None:
            state_out[state_rows[seq_idx]].copy_(
                state.transpose(-1, -2).to(state_out.dtype)
            )

    if not writes_result_directly:
        result.copy_(result_work[None].to(result.dtype))

    return result, state_out


def packed_prefill_prepare_torch(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    *,
    query: torch.Tensor | None = None,
    key: torch.Tensor | None = None,
    value: torch.Tensor | None = None,
    g: torch.Tensor | None = None,
    beta: torch.Tensor | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    """Reference Qwen packed prefill q/k/v split, q/k l2norm, and gate prep."""

    if mixed_qkv.ndim != 3 or mixed_qkv.shape[0] != 1:
        raise ValueError(f"mixed_qkv must be [1, T, D], got {tuple(mixed_qkv.shape)}")
    if a.ndim != 3 or b.ndim != 3:
        raise ValueError(f"a/b must be [1, T, H], got {tuple(a.shape)} / {tuple(b.shape)}")
    _, seqlen, packed_dim = mixed_qkv.shape
    num_v_heads = a.shape[2]
    if a.shape != (1, seqlen, num_v_heads) or b.shape != (1, seqlen, num_v_heads):
        raise ValueError(
            f"a/b must be {(1, seqlen, num_v_heads)}, "
            f"got {tuple(a.shape)} / {tuple(b.shape)}"
        )
    if value is not None:
        if value.ndim != 4 or value.shape[:2] != (1, seqlen):
            raise ValueError(
                f"value must be [1, T, V, D], got {tuple(value.shape)}"
            )
        num_v_heads = value.shape[2]
        head_dim = value.shape[3]
        expected_value = (1, seqlen, num_v_heads, head_dim)
    elif query is not None:
        if query.ndim != 4 or query.shape[:2] != (1, seqlen):
            raise ValueError(
                f"query must be [1, T, K, D], got {tuple(query.shape)}"
            )
        head_dim = query.shape[3]
        expected_value = (1, seqlen, num_v_heads, head_dim)
    else:
        if packed_dim % (3 * num_v_heads) != 0:
            raise ValueError(
                "mixed_qkv last dim is ambiguous without output buffers; expected "
                f"equal-head 3 * H * D layout, got {packed_dim=} {num_v_heads=}"
            )
        head_dim = packed_dim // (3 * num_v_heads)
        expected_value = (1, seqlen, num_v_heads, head_dim)
    qk_packed_dim = packed_dim - num_v_heads * head_dim
    if qk_packed_dim <= 0 or qk_packed_dim % (2 * head_dim) != 0:
        raise ValueError(
            "mixed_qkv last dim must be 2 * K * D + V * D, got "
            f"{packed_dim=} {num_v_heads=} {head_dim=}"
        )
    num_k_heads = qk_packed_dim // (2 * head_dim)
    if num_v_heads % num_k_heads != 0:
        raise ValueError(
            f"num_v_heads must be a multiple of num_k_heads, got {num_v_heads=} "
            f"{num_k_heads=}"
        )
    if query is not None and query.shape != (1, seqlen, num_k_heads, head_dim):
        raise ValueError(
            f"query shape must be {(1, seqlen, num_k_heads, head_dim)}, "
            f"got {tuple(query.shape)}"
        )
    if key is not None and key.shape != (1, seqlen, num_k_heads, head_dim):
        raise ValueError(
            f"key shape must be {(1, seqlen, num_k_heads, head_dim)}, got {tuple(key.shape)}"
        )
    if value is not None and value.shape != expected_value:
        raise ValueError(f"value shape must be {expected_value}, got {tuple(value.shape)}")
    expected_3d = (1, seqlen, num_v_heads)
    if g is not None and g.shape != expected_3d:
        raise ValueError(f"g shape must be {expected_3d}, got {tuple(g.shape)}")
    if beta is not None and beta.shape != expected_3d:
        raise ValueError(f"beta shape must be {expected_3d}, got {tuple(beta.shape)}")

    split = [num_k_heads * head_dim, num_k_heads * head_dim, num_v_heads * head_dim]
    query_ref, key_ref, value_ref = torch.split(mixed_qkv, split, dim=-1)
    query_ref = query_ref.reshape(1, seqlen, num_k_heads, head_dim).float()
    key_ref = key_ref.reshape(1, seqlen, num_k_heads, head_dim).float()
    value_ref = value_ref.reshape(expected_value)
    query_ref = query_ref * torch.rsqrt((query_ref * query_ref).sum(dim=-1, keepdim=True) + 1e-6)
    key_ref = key_ref * torch.rsqrt((key_ref * key_ref).sum(dim=-1, keepdim=True) + 1e-6)
    g_ref = -A_log.float().exp().view(1, 1, num_v_heads) * F.softplus(
        a.float() + dt_bias.float().view(1, 1, num_v_heads)
    )
    beta_ref = b.float().sigmoid()

    if query is None:
        query = torch.empty(
            (1, seqlen, num_k_heads, head_dim),
            device=mixed_qkv.device,
            dtype=mixed_qkv.dtype,
        )
    if key is None:
        key = torch.empty_like(query)
    if value is None:
        value = torch.empty(expected_value, device=mixed_qkv.device, dtype=mixed_qkv.dtype)
    if g is None:
        g = torch.empty(expected_3d, device=mixed_qkv.device, dtype=torch.float32)
    if beta is None:
        beta = torch.empty(expected_3d, device=mixed_qkv.device, dtype=mixed_qkv.dtype)

    query.copy_(query_ref)
    key.copy_(key_ref)
    value.copy_(value_ref)
    g.copy_(g_ref)
    beta.copy_(beta_ref)
    return query, key, value, g, beta


def gated_rmsnorm_torch(
    hidden_states: torch.Tensor,
    gate: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1e-6,
    *,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Reference Qwen gated RMSNorm.

    Matches ``Qwen3_5RMSNormGated``: RMS-normalize in fp32, round the
    normalized activations back to the input dtype before applying the fp32
    norm weight and fp32 SiLU gate, then return the input dtype.
    """

    if gate is None:
        raise ValueError("gated_rmsnorm_torch requires a gate tensor")
    if hidden_states.shape != gate.shape:
        raise ValueError(
            "hidden_states and gate must have the same shape, got "
            f"{tuple(hidden_states.shape)} and {tuple(gate.shape)}"
        )
    if weight.shape != (hidden_states.shape[-1],):
        raise ValueError(
            f"weight shape must be {(hidden_states.shape[-1],)}, got {tuple(weight.shape)}"
        )
    if out is not None and out.shape != hidden_states.shape:
        raise ValueError(
            f"out shape must be {tuple(hidden_states.shape)}, got {tuple(out.shape)}"
        )

    input_dtype = hidden_states.dtype
    hidden_f = hidden_states.to(torch.float32)
    variance = hidden_f.pow(2).mean(-1, keepdim=True)
    normalized = hidden_f * torch.rsqrt(variance + eps)
    result = weight * normalized.to(input_dtype)
    result = result * F.silu(gate.to(torch.float32))
    result = result.to(input_dtype)
    if out is not None:
        out.copy_(result)
        return out
    return result


